const VERSION='gun-payi-v4.1.1';
const PREFIX='gun-payi-';
const SHELL=['/','/index.html','/style.css','/app.js','/core.js','/plan-icons.js','/microphone.js','/telegram.js','/backup.js','/updates.js','/controls.js','/voice.js','/dictation-core.js','/reminders.js','/reminders-core.js','/manifest.webmanifest','/icons/icon-192.png','/icons/icon-512.png','/icons/maskable-512.png','/icons/apple-touch-icon.png'];
// Navigation responses must not retain a followed redirect's URL history.
function cleanResponse(response){const headers=new Headers(response.headers);headers.delete('content-encoding');headers.delete('content-length');return new Response(response.body,{status:response.status,statusText:response.statusText,headers});}
function validResponse(response,path){if(!response?.ok||['opaque','opaqueredirect','error'].includes(response.type))return false;if(response.url&&new URL(response.url).origin!==self.location.origin)return false;const type=response.headers.get('content-type')||'';return path.endsWith('.js')?/javascript|ecmascript/.test(type):path.endsWith('.css')?/text\/css/.test(type):path==='/'||path==='/index.html'?/text\/html/.test(type):true;}
async function fresh(path){const response=await fetch(new Request(new URL(path,self.location.origin),{cache:'no-store',redirect:'follow'}));if(!validResponse(response,path))throw Error('Uygulama dosyası alınamadı: '+path);return cleanResponse(response);}
async function cached(name,path){try{return await (await caches.open(name)).match(path);}catch{return null;}}
async function previous(path){try{const names=(await caches.keys()).filter(k=>k.startsWith(PREFIX)&&k!==VERSION).reverse();for(const name of names){const response=await cached(name,path);if(validResponse(response,path))return cleanResponse(response);}}catch{}return null;}
async function remember(path,response){try{const cache=await caches.open(VERSION);await cache.put(path,response.clone());if(path==='/index.html')await cache.put('/',response.clone());}catch{/* Storage pressure must not prevent a network page from opening. */}}
const offlinePage=()=>new Response('<!doctype html><html lang="tr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Gün Payı</title><style>body{font:17px system-ui;margin:12vh auto;padding:24px;max-width:440px;color:#453b50;background:#faf9fc;line-height:1.6}a{display:inline-block;padding:12px 20px;border-radius:14px;color:white;background:#8863a0;text-decoration:none}</style><h1>Bağlantı kurulamadı</h1><p>İnternet bağlantın geldiğinde yeniden dene. Kayıtlı planların ve notların bu cihazda korunur.</p><a href="/">Yeniden dene</a></html>',{status:503,headers:{'content-type':'text/html;charset=utf-8','cache-control':'no-store'}});
async function page(){const saved=await cached(VERSION,'/index.html')||await cached(VERSION,'/');if(validResponse(saved,'/index.html'))return cleanResponse(saved);try{const response=await fresh('/');await remember('/index.html',response);return response;}catch{return await previous('/index.html')||await previous('/')||offlinePage();}}
async function asset(path){const saved=await cached(VERSION,path);if(validResponse(saved,path))return cleanResponse(saved);try{const response=await fresh(path);await remember(path,response);return response;}catch{return await previous(path)||new Response('Uygulama dosyası şu anda alınamıyor.',{status:503,headers:{'content-type':'text/plain;charset=utf-8'}});}}
self.addEventListener('install',event=>event.waitUntil((async()=>{try{const cache=await caches.open(VERSION),html=await fresh('/');await cache.put('/',html.clone());await cache.put('/index.html',html);await Promise.all(SHELL.filter(path=>path!=='/'&&path!=='/index.html').map(async path=>cache.put(path,await fresh(path))));await self.skipWaiting();}catch(error){try{await caches.delete(VERSION);}catch{}throw error;}})()));
self.addEventListener('message',event=>{if(event.data?.type==='ACTIVATE_UPDATE')event.waitUntil(self.skipWaiting());if(event.data?.type==='APP_VERSION')event.ports?.[0]?.postMessage({type:'APP_VERSION',version:VERSION});});
self.addEventListener('activate',event=>event.waitUntil((async()=>{try{const older=(await caches.keys()).filter(k=>k.startsWith(PREFIX)&&k!==VERSION);for(const name of older.slice(0,-1))try{await caches.delete(name);}catch{}}catch{}await self.clients.claim();})()));
self.addEventListener('fetch',event=>{const url=new URL(event.request.url);if(event.request.method!=='GET'||url.origin!==self.location.origin)return;if(event.request.mode==='navigate'&&(url.pathname==='/'||url.pathname==='/index.html')){event.respondWith(page());return;}if(SHELL.includes(url.pathname))event.respondWith(asset(url.pathname));});
self.addEventListener('notificationclick',event=>{event.notification.close();const raw=event.notification.data?.url||'/';const target=new URL(raw,self.location.origin);const safe=target.origin===self.location.origin?target.href:self.location.origin+'/';event.waitUntil((async()=>{const windows=await self.clients.matchAll({type:'window',includeUncontrolled:true});for(const client of windows){if(new URL(client.url).origin===self.location.origin){await client.navigate(safe);return client.focus();}}return self.clients.openWindow(safe)})());});
